26	// pushRefIfNeeded pushes a custom ref to the given target if it exists locally.
27	// Custom refs (under refs/entire/) don't have remote-tracking refs, so there's
28	// no "has unpushed" optimization — we always attempt the push and let git handle
29	// the no-op case.
30	func pushRefIfNeeded(ctx context.Context, target string, refName plumbing.ReferenceName) error {
31		repo, err := OpenRepository(ctx)
32		if err != nil {
33			return nil //nolint:nilerr // Hook must be silent on failure
34		}
35	
36		if _, err := repo.Reference(refName, true); err != nil {
37			return nil //nolint:nilerr // Ref doesn't exist locally, nothing to push
38		}
39	
40		return doPushRef(ctx, target, refName)
41	}
42	
43	// tryPushRef attempts to push a custom ref using an explicit refspec.
44	func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
45		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
46		defer cancel()
47	
48		// Use --no-verify to prevent recursive hook calls (this runs inside pre-push)
49		refSpec := fmt.Sprintf("%s:%s", refName, refName)
50		cmd := CheckpointGitCommand(ctx, target, "push", "--no-verify", target, refSpec)
51	
52		output, err := cmd.CombinedOutput()
53		if err != nil {
54			if strings.Contains(string(output), "non-fast-forward") ||
55				strings.Contains(string(output), "rejected") {
56				return errors.New("non-fast-forward")
57			}
58			return fmt.Errorf("push failed: %s", output)
59		}
60		return nil
61	}
62	
63	// doPushRef pushes a custom ref with fetch+merge recovery on conflict.
64	func doPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
65		displayTarget := target
66		if isURL(target) {
67			displayTarget = "checkpoint remote"
68		}
69	
70		shortRef := shortRefName(refName)
71		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
72		stop := startProgressDots(os.Stderr)
73	
74		if err := tryPushRef(ctx, target, refName); err == nil {
75			stop(" done")
76			printSettingsCommitHint(ctx, target)
77			return nil
78		}
79		stop("")
80	
81		fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", shortRef)
82		stop = startProgressDots(os.Stderr)
83	
84		if err := fetchAndMergeRef(ctx, target, refName); err != nil {
85			stop("")
86			fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", shortRef, err)
87			printCheckpointRemoteHint(target)
88			return nil
89		}
90		stop(" done")
91	
92		fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
93		stop = startProgressDots(os.Stderr)
94	
95		if err := tryPushRef(ctx, target, refName); err != nil {
96			stop("")
97			fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", shortRef, err)
98			printCheckpointRemoteHint(target)
99		} else {
100			stop(" done")
101			printSettingsCommitHint(ctx, target)
102		}
103	
104		return nil
105	}
106	
107	// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
108	// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
109	//
110	// For /full/current: if the remote has archived generations not present locally,
111	// another machine rotated. In that case, local data is merged into the latest
112	// archived generation instead of into /full/current (see handleRotationConflict).
113	func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
114		ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
115		defer cancel()
116	
117		// Fetch to a temp ref
118		tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
119		tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
120		refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)
121	
122		// Use --filter=blob:none for a partial fetch that downloads only commits
123		// and trees, skipping blobs. The merge only needs the tree structure to
124		// combine entries; blobs are already local or fetched on demand.
125		fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, refSpec)
126		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
127		if output, err := fetchCmd.CombinedOutput(); err != nil {
128			return fmt.Errorf("fetch failed: %s", output)
129		}
130	
131		repo, err := OpenRepository(ctx)
132		if err != nil {
133			return fmt.Errorf("failed to open repository: %w", err)
134		}
135		defer func() {
136			_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
137		}()
138	
139		// Check for rotation conflict on /full/current
140		if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
141			remoteOnlyArchives, detectErr := detectRemoteOnlyArchives(ctx, target, repo)
142			if detectErr == nil && len(remoteOnlyArchives) > 0 {
143				return handleRotationConflict(ctx, target, repo, refName, tmpRefName, remoteOnlyArchives)
144			}
145		}
146	
147		// Standard tree merge (no rotation detected)
148		localRef, err := repo.Reference(refName, true)
149		if err != nil {
150			return fmt.Errorf("failed to get local ref: %w", err)
151		}
152		localCommit, err := repo.CommitObject(localRef.Hash())
153		if err != nil {
154			return fmt.Errorf("failed to get local commit: %w", err)
155		}
156		localTree, err := localCommit.Tree()
157		if err != nil {
158			return fmt.Errorf("failed to get local tree: %w", err)
159		}
160	
161		remoteRef, err := repo.Reference(tmpRefName, true)
162		if err != nil {
163			return fmt.Errorf("failed to get remote ref: %w", err)
164		}
165		remoteCommit, err := repo.CommitObject(remoteRef.Hash())
166		if err != nil {
167			return fmt.Errorf("failed to get remote commit: %w", err)
168		}
169		remoteTree, err := remoteCommit.Tree()
170		if err != nil {
171			return fmt.Errorf("failed to get remote tree: %w", err)
172		}
173	
174		entries := make(map[string]object.TreeEntry)
175		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
176			return fmt.Errorf("failed to flatten local tree: %w", err)
177		}
178		if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
179			return fmt.Errorf("failed to flatten remote tree: %w", err)
180		}
181	
182		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
183		if err != nil {
184			return fmt.Errorf("failed to build merged tree: %w", err)
185		}
186	
187		mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
188			[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
189			"Merge remote "+shortRefName(refName))
190		if err != nil {
191			return fmt.Errorf("failed to create merge commit: %w", err)
192		}
193	
194		newRef := plumbing.NewHashReference(refName, mergeCommitHash)
195		if err := repo.Storer.SetReference(newRef); err != nil {
196			return fmt.Errorf("failed to update ref: %w", err)
197		}
198	
199		return nil
200	}
201	
202	// detectRemoteOnlyArchives discovers archived generation refs on the remote
203	// that don't exist locally. Returns them sorted ascending (oldest first).
204	func detectRemoteOnlyArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
205		ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
206		defer cancel()
207	
208		cmd := CheckpointGitCommand(ctx, target, "ls-remote", target, paths.V2FullRefPrefix+"*")
209		cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
210		output, err := cmd.Output()
211		if err != nil {
212			return nil, fmt.Errorf("ls-remote failed: %w", err)
213		}
214	
215		var remoteOnly []string
216		for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
217			if line == "" {
218				continue
219			}
220			parts := strings.Fields(line)
221			if len(parts) < 2 {
222				continue
223			}
224			refName := parts[1]
225			suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
226			if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
227				continue
228			}
229			// Only check for existence, not hash equality. A locally-present archive
230			// could be stale if another machine updated it via rotation conflict recovery,
231			// but that's unlikely and the checkpoints are still on /main regardless.
232			if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
233				remoteOnly = append(remoteOnly, suffix)
234			}
235		}
236	
237		sort.Strings(remoteOnly)
238		return remoteOnly, nil
239	}
240	
241	// handleRotationConflict handles the case where remote /full/current was rotated.
242	// Merges local /full/current into the latest remote archived generation to avoid
243	// duplicating checkpoint data, then adopts remote's /full/current as local.
244	func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
245		// Use the latest remote-only archive
246		latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
247		archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)
248	
249		// Fetch the latest archived generation
250		archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
251		archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
252		fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, archiveRefSpec)
253		fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
254		if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
255			return fmt.Errorf("fetch archived generation failed: %s", output)
256		}
257		defer func() {
258			_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
259		}()
260	
261		// Get archived generation state
262		archiveRef, err := repo.Reference(archiveTmpRef, true)
263		if err != nil {
264			return fmt.Errorf("failed to get archived ref: %w", err)
265		}
266		archiveCommit, err := repo.CommitObject(archiveRef.Hash())
267		if err != nil {
268			return fmt.Errorf("failed to get archive commit: %w", err)
269		}
270		archiveTree, err := archiveCommit.Tree()
271		if err != nil {
272			return fmt.Errorf("failed to get archive tree: %w", err)
273		}
274	
275		// Get local /full/current state
276		localRef, err := repo.Reference(refName, true)
277		if err != nil {
278			return fmt.Errorf("failed to get local ref: %w", err)
279		}
280		localCommit, err := repo.CommitObject(localRef.Hash())
281		if err != nil {
282			return fmt.Errorf("failed to get local commit: %w", err)
283		}
284		localTree, err := localCommit.Tree()
285		if err != nil {
286			return fmt.Errorf("failed to get local tree: %w", err)
287		}
288	
289		// Tree-merge local /full/current into archived generation.
290		// Git content-addressing deduplicates shared shard paths automatically.
291		entries := make(map[string]object.TreeEntry)
292		if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
293			return fmt.Errorf("failed to flatten archive tree: %w", err)
294		}
295		if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
296			return fmt.Errorf("failed to flatten local tree: %w", err)
297		}
298	
299		// Update generation.json timestamps if present in the merged tree.
300		// Use the local /full/current HEAD commit time as the newest checkpoint time
301		// (more accurate than time.Now() for cleanup scheduling).
302		if genEntry, exists := entries[paths.GenerationFileName]; exists {
303			if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
304				entries[paths.GenerationFileName] = updatedEntry
305			} else {
306				logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
307					slog.String("error", updateErr.Error()),
308				)
309			}
310		}
311	
312		mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
313		if err != nil {
314			return fmt.Errorf("failed to build merged tree: %w", err)
315		}
316	
317		// Create commit parented on archive's commit (fast-forward)
318		mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
319			[]plumbing.Hash{archiveRef.Hash()},
320			"Merge local checkpoints into archived generation")
321		if err != nil {
322			return fmt.Errorf("failed to create merge commit: %w", err)
323		}
324	
325		// Update local archived ref and push it
326		newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
327		if err := repo.Storer.SetReference(newArchiveRef); err != nil {
328			return fmt.Errorf("failed to update archive ref: %w", err)
329		}
330	
331		if pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
332			return fmt.Errorf("failed to push updated archive: %w", pushErr)
333		}
334	
335		// Adopt remote's /full/current as local
336		remoteRef, err := repo.Reference(tmpRefName, true)
337		if err != nil {
338			return fmt.Errorf("failed to get fetched /full/current: %w", err)
339		}
340		adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
341		if err := repo.Storer.SetReference(adoptedRef); err != nil {
342			return fmt.Errorf("failed to adopt remote /full/current: %w", err)
343		}
344	
345		return nil
346	}
347	
348	// updateGenerationTimestamps reads generation.json from a blob, updates
349	// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
350	// an updated tree entry. Uses the local commit timestamp rather than
351	// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
352	func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
353		blob, err := repo.BlobObject(genBlobHash)
354		if err != nil {
355			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
356		}
357		reader, err := blob.Reader()
358		if err != nil {
359			return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
360		}
361		defer reader.Close()
362	
363		data, err := io.ReadAll(reader)
364		if err != nil {
365			return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
366		}
367	
368		var gen checkpoint.GenerationMetadata
369		if err := json.Unmarshal(data, &gen); err != nil {
370			return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
371		}
372	
373		if newestFromLocal.After(gen.NewestCheckpointAt) {
374			gen.NewestCheckpointAt = newestFromLocal
375		}
376	
377		updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
378		if err != nil {
379			return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
380		}
381	
382		newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
383		if err != nil {
384			return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
385		}
386	
387		return object.TreeEntry{
388			Name: paths.GenerationFileName,
389			Mode: filemode.Regular,
390			Hash: newBlobHash,
391		}, nil
392	}
393	
394	// pushV2Refs pushes v2 checkpoint refs to the target.
395	// Pushes /main, /full/current, and the latest archived generation (if any).
396	// Older archived generations are immutable and were pushed when created.
397	func pushV2Refs(ctx context.Context, target string) {
398		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
399		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally
400	
401		// Push only the latest archived generation (most likely to be newly created)
402		repo, err := OpenRepository(ctx)
403		if err != nil {
404			return
405		}
406		store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
407		archived, err := store.ListArchivedGenerations()
408		if err != nil || len(archived) == 0 {
409			return
410		}
411		latest := archived[len(archived)-1]
412		_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
413	}
414	
415	// shortRefName returns a human-readable short form of a ref name for log output.
416	// e.g., "refs/entire/checkpoints/v2/main" -> "v2/main"
417	func shortRefName(refName plumbing.ReferenceName) string {
418		const prefix = "refs/entire/checkpoints/"
419		s := string(refName)
420		if strings.HasPrefix(s, prefix) {
421			return s[len(prefix):]
422		}
423		return s
424	}
425

