	defer cancel()

	cmd := CheckpointGitCommand(ctx, target, "ls-remote", target, paths.V2FullRefPrefix+"*")
	cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("ls-remote failed: %w", err)
	}

	var remoteOnly []string
	for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
		if line == "" {
			continue
		}
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		refName := parts[1]
		suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
		if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
			continue
		}
		// Only check for existence, not hash equality. A locally-present archive
		// could be stale if another machine updated it via rotation conflict recovery,
		// but that's unlikely and the checkpoints are still on /main regardless.
		if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
			remoteOnly = append(remoteOnly, suffix)
		}
	}

	sort.Strings(remoteOnly)
	return remoteOnly, nil
}

// handleRotationConflict handles the case where remote /full/current was rotated.
// Merges local /full/current into the latest remote archived generation to avoid
// duplicating checkpoint data, then adopts remote's /full/current as local.
func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
	// Use the latest remote-only archive
	latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
	archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)

	// Fetch the latest archived generation
	archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
	archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
	fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, archiveRefSpec)
	fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
	if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
		return fmt.Errorf("fetch archived generation failed: %s", output)
	}
	defer func() {
		_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
	}()

	// Get archived generation state
	archiveRef, err := repo.Reference(archiveTmpRef, true)
	if err != nil {
		return fmt.Errorf("failed to get archived ref: %w", err)
	}
	archiveCommit, err := repo.CommitObject(archiveRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get archive commit: %w", err)
	}
	archiveTree, err := archiveCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get archive tree: %w", err)
	}

	// Get local /full/current state
	localRef, err := repo.Reference(refName, true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}
	localCommit, err := repo.CommitObject(localRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get local commit: %w", err)
	}
	localTree, err := localCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get local tree: %w", err)
	}

	// Tree-merge local /full/current into archived generation.
	// Git content-addressing deduplicates shared shard paths automatically.
	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten archive tree: %w", err)
	}
	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten local tree: %w", err)
	}

	// Update generation.json timestamps if present in the merged tree.
	// Use the local /full/current HEAD commit time as the newest checkpoint time
	// (more accurate than time.Now() for cleanup scheduling).
	if genEntry, exists := entries[paths.GenerationFileName]; exists {
		if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
			entries[paths.GenerationFileName] = updatedEntry
		} else {
			logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
				slog.String("error", updateErr.Error()),
			)
		}
	}

	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build merged tree: %w", err)
	}

	// Create commit parented on archive's commit (fast-forward)
	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
		[]plumbing.Hash{archiveRef.Hash()},
		"Merge local checkpoints into archived generation")
	if err != nil {
		return fmt.Errorf("failed to create merge commit: %w", err)
	}

	// Update local archived ref and push it
	newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
	if err := repo.Storer.SetReference(newArchiveRef); err != nil {
		return fmt.Errorf("failed to update archive ref: %w", err)
	}

	if _, pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
		return fmt.Errorf("failed to push updated archive: %w", pushErr)
	}

	// Adopt remote's /full/current as local
	remoteRef, err := repo.Reference(tmpRefName, true)
	if err != nil {
		return fmt.Errorf("failed to get fetched /full/current: %w", err)
	}
	adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
	if err := repo.Storer.SetReference(adoptedRef); err != nil {
		return fmt.Errorf("failed to adopt remote /full/current: %w", err)
	}

	return nil
}

// updateGenerationTimestamps reads generation.json from a blob, updates
// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
// an updated tree entry. Uses the local commit timestamp rather than
// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
	blob, err := repo.BlobObject(genBlobHash)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
	}
	reader, err := blob.Reader()
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
	}
	defer reader.Close()

	data, err := io.ReadAll(reader)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
	}

	var gen checkpoint.GenerationMetadata
	if err := json.Unmarshal(data, &gen); err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
	}

	if newestFromLocal.After(gen.NewestCheckpointAt) {
		gen.NewestCheckpointAt = newestFromLocal
	}

	updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
	}

	newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
	}

	return object.TreeEntry{
		Name: paths.GenerationFileName,
		Mode: filemode.Regular,
		Hash: newBlobHash,
	}, nil
}

// pushV2Refs pushes v2 checkpoint refs to the target.
// Pushes /main, /full/current, and the latest archived generation (if any).
// Older archived generations are immutable and were pushed when created.
func pushV2Refs(ctx context.Context, target string) {
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally

	// Push only the latest archived generation (most likely to be newly created)
	repo, err := OpenRepository(ctx)
	if err != nil {
		return
	}
	store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
	archived, err := store.ListArchivedGenerations()
	if err != nil || len(archived) == 0 {
		return
	}
	latest := archived[len(archived)-1]
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
}

// shortRefName returns a human-readable short form of a ref name for log output.
// e.g., "refs/entire/checkpoints/v2/main" -> "v2/main"
func shortRefName(refName plumbing.ReferenceName) string {
	const prefix = "refs/entire/checkpoints/"
	s := string(refName)
	if strings.HasPrefix(s, prefix) {
		return s[len(prefix):]
	}
	return s
}

package strategy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
// The target can be a remote name (e.g., "origin") or a URL for direct push.
// When pushing to a URL, the "has unpushed" optimization is skipped since there are
// no remote tracking refs — git itself handles the no-op case.
// Does not check any settings — callers are responsible for gating.
func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Check if branch exists locally
	branchRef := plumbing.NewBranchReferenceName(branchName)
	localRef, err := repo.Reference(branchRef, true)
	if err != nil {
		// No branch, nothing to push
		return nil //nolint:nilerr // Expected when no sessions exist yet
	}

	// Only check remote tracking refs when target is a remote name (not a URL).
	// URLs don't have tracking refs, so we always attempt the push and let git handle it.
	if !isURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
		return nil
	}

	return doPushBranch(ctx, target, branchName)
}

// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
	// Check for remote tracking ref: refs/remotes/<remote>/<branch>
	remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
	remoteRef, err := repo.Reference(remoteRefName, true)
	if err != nil {
		// Remote branch doesn't exist yet - we have content to push
		return true
	}

	// If local and remote point to same commit, nothing to sync
	// This is the only case where we skip - any difference needs handling
	return localHash != remoteRef.Hash()
}

// doPushBranch pushes the given branch to the target with fetch+merge recovery.
// The target can be a remote name or a URL.
func doPushBranch(ctx context.Context, target, branchName string) error {
	displayTarget := target
	if isURL(target) {
		displayTarget = "checkpoint remote"
	}

	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
	stop := startProgressDots(os.Stderr)

	// Try pushing first
	if result, err := tryPushSessionsCommon(ctx, target, branchName); err == nil {
		finishPush(stop, result, ctx, target)
		return nil
	}
	stop("")

	// Push failed - likely non-fast-forward. Try to fetch and rebase.
	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
	stop = startProgressDots(os.Stderr)

	if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
		printCheckpointRemoteHint(target)
		return nil // Don't fail the main push
	}
	stop(" done")

	// Try pushing again after rebase
	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
	stop = startProgressDots(os.Stderr)

	if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
		printCheckpointRemoteHint(target)
	} else {
		finishPush(stop, result, ctx, target)
	}

	return nil
}

// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
// Only prints when the target is a URL (not the user's default remote).
func printCheckpointRemoteHint(target string) {
	if !isURL(target) {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
	fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
}

// settingsHintOnce ensures the settings commit hint prints at most once per process.
var settingsHintOnce sync.Once

// printSettingsCommitHint prints a hint after a successful checkpoint remote push
// when the committed .entire/settings.json does not contain a checkpoint_remote config.
// entire.io discovers the external checkpoint repo by reading the committed project
// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
// (not just in settings.local.json or uncommitted local changes).
// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
// single pre-push invocation.
func printSettingsCommitHint(ctx context.Context, target string) {
	if !isURL(target) {
		return
	}
	settingsHintOnce.Do(func() {
		if isCheckpointRemoteCommitted(ctx) {
			return
		}
		fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
	})
}

// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
// at HEAD contains a valid checkpoint_remote configuration. This is the true
// discoverability check: entire.io reads from committed project settings, not from
// local overrides or uncommitted changes.
func isCheckpointRemoteCommitted(ctx context.Context) bool {
	cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
	output, err := cmd.Output()
	if err != nil {
		return false // file doesn't exist at HEAD
	}
	// Parse the committed content and check for checkpoint_remote
	committed, err := settings.LoadFromBytes(output)
	if err != nil {
		return false
	}
	return committed.GetCheckpointRemote() != nil
}

// pushResult describes what happened during a push attempt.
type pushResult struct {
	// upToDate is true when the remote already had all commits (nothing transferred).
	upToDate bool
}

// parsePushResult checks git push output for known status strings and returns
// a pushResult. git prints "Everything up-to-date" to stderr when nothing was pushed.
func parsePushResult(output string) pushResult {
	return pushResult{
		upToDate: strings.Contains(output, "Everything up-to-date") ||
			strings.Contains(output, "everything up-to-date"),
	}
}

// finishPush stops the progress dots and prints "already up-to-date" or "done"
// depending on the push result. Only prints the settings commit hint when new
// content was actually pushed.
func finishPush(stop func(string), result pushResult, ctx context.Context, target string) {
	if result.upToDate {
		stop(" already up-to-date")
	} else {
		stop(" done")
		printSettingsCommitHint(ctx, target)
	}
}

// tryPushSessionsCommon attempts to push the sessions branch.
func tryPushSessionsCommon(ctx context.Context, remote, branchName string) (pushResult, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Use --no-verify to prevent recursive hook calls
	cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", remote, branchName)

	output, err := cmd.CombinedOutput()
	outputStr := string(output)
	if err != nil {
		// Check if it's a non-fast-forward error (we can try to recover)
		if strings.Contains(outputStr, "non-fast-forward") ||
			strings.Contains(outputStr, "rejected") {
			return pushResult{}, errors.New("non-fast-forward")
		}
		return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
	}

	return parsePushResult(outputStr), nil
}

// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
// on top of the remote tip. Since checkpoint shards use unique paths, rebases
// always apply cleanly.
// The target can be a remote name or a URL.
func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Determine fetch refspec. When target is a URL, use a temp ref;
	// when it's a remote name, use the standard remote-tracking ref.
	var fetchedRefName plumbing.ReferenceName
	var refSpec string
	if isURL(target) {
		tmpRef := "refs/entire-fetch-tmp/" + branchName
		refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
		fetchedRefName = plumbing.ReferenceName(tmpRef)
	} else {
		refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
		fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
	}

	// Use git CLI for fetch (go-git's fetch can be tricky with auth).
	// Use --filter=blob:none for a partial fetch that downloads only commits
	// and trees, skipping blobs. The merge only needs the tree structure to
	// combine entries; blobs are already local or fetched on demand.
	fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, refSpec)
	if output, err := fetchCmd.CombinedOutput(); err != nil {
		return fmt.Errorf("fetch failed: %s", output)
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Reconcile disconnected metadata branches before rebasing.
	// The fetch above updated the remote-tracking ref, so reconciliation
	// can compare fresh local vs remote. If disconnected (empty-orphan bug),
	// this cherry-picks local commits onto remote tip, updating the local ref.
	// If reconciliation fails, abort — proceeding to rebase on disconnected
	// branches would silently combine unrelated histories.
	if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
		return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
	}

	// Get local branch (re-read after potential reconciliation update)
	localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}

	// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
	remoteRef, err := repo.Reference(fetchedRefName, true)
	if err != nil {
		return fmt.Errorf("failed to get remote ref: %w", err)
	}

	// If local is already at or behind remote, fast-forward
	if localRef.Hash() == remoteRef.Hash() {
		return nil
	}

	// Find merge base
	repoPath, err := getRepoPath(repo)
	if err != nil {
		return fmt.Errorf("failed to get repo path: %w", err)
	}
	mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
	if err != nil {
		return fmt.Errorf("failed to find merge base: %w", err)
	}

	// If local is ancestor of remote (merge base == local), fast-forward to remote
	if mergeBase == localRef.Hash() {
		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
		if err := repo.Storer.SetReference(ref); err != nil {
			return fmt.Errorf("failed to fast-forward branch ref: %w", err)
		}
		if isURL(target) {
			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
		}
		return nil
	}

	// Collect commits reachable from local but not from remote and cherry-pick
	// them onto the remote tip. This preserves local-only commits even when the
	// local metadata branch already contains old merge commits, while avoiding
	// replaying shared ancestors older than the true merge-base.
	localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to collect local commits: %w", err)
	}

	if len(localCommits) == 0 {
		// No local-only commits — just point to remote
		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
		if err := repo.Storer.SetReference(ref); err != nil {
			return fmt.Errorf("failed to update branch ref: %w", err)
		}
		if isURL(target) {
			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
		}
		return nil
	}

	newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
	if err != nil {
		return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
	}

	// Update branch ref
	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
	if err := repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch ref: %w", err)
	}

	// Clean up temp ref if we used one (best-effort, not critical if it fails)
	if isURL(target) {
		_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
	}

	return nil
}

// getMergeBase returns the merge base hash of two commits, or an error if they
// have no common ancestor.
func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
	cmd.Dir = repoPath
	output, err := cmd.Output()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
	}

	return plumbing.NewHash(strings.TrimSpace(string(output))), nil
}

// collectCommitsSince returns non-merge commits reachable from tip but not from
// exclude, ordered oldest-first in topological order.
func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	// cherryPickOnto computes each commit's delta against its first parent, so
	// replaying merge commits would incorrectly re-apply changes that arrived via
	// non-first-parent history. Limit the replay set to non-merge commits.
	cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
	cmd.Dir = repoPath
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("git rev-list failed: %w", err)
	}

	lines := strings.Fields(string(output))
	if len(lines) > MaxCommitTraversalDepth {
		return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
	}

	commits := make([]*object.Commit, 0, len(lines))
	for _, line := range lines {
		hash := plumbing.NewHash(line)
		commit, commitErr := repo.CommitObject(hash)
		if commitErr != nil {
			return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
		}
		if len(commit.ParentHashes) > 1 {
			continue
		}
		commits = append(commits, commit)
	}

	return commits, nil
}

// startProgressDots prints dots to w every second until the returned stop function
// is called. The stop function prints the given suffix and a newline.
func startProgressDots(w io.Writer) func(suffix string) {
	done := make(chan struct{})
	stopped := make(chan struct{})
	go func() {
		defer close(stopped)
		ticker := time.NewTicker(time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-done:
				return
			case <-ticker.C:
				fmt.Fprint(w, ".")
			}
		}
	}()
	return func(suffix string) {
		close(done)
		<-stopped // Wait for goroutine to finish before writing suffix
		fmt.Fprintln(w, suffix)
	}
}

// isURL returns true if the target looks like a URL rather than a git remote name.
func isURL(target string) bool {
	return strings.Contains(target, "://") || strings.Contains(target, "@")
}

// createMergeCommitCommon creates a merge commit with multiple parents.
func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
	authorName, authorEmail := GetGitAuthorFromRepo(repo)
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: parents,
		Author:       sig,
		Committer:    sig,
		Message:      message,
	}

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

package strategy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"sync"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// pushBranchIfNeeded pushes a branch to the given target if it has unpushed changes.
// The target can be a remote name (e.g., "origin") or a URL for direct push.
// When pushing to a URL, the "has unpushed" optimization is skipped since there are
// no remote tracking refs — git itself handles the no-op case.
// Does not check any settings — callers are responsible for gating.
func pushBranchIfNeeded(ctx context.Context, target, branchName string) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	// Check if branch exists locally
	branchRef := plumbing.NewBranchReferenceName(branchName)
	localRef, err := repo.Reference(branchRef, true)
	if err != nil {
		// No branch, nothing to push
		return nil //nolint:nilerr // Expected when no sessions exist yet
	}

	// Only check remote tracking refs when target is a remote name (not a URL).
	// URLs don't have tracking refs, so we always attempt the push and let git handle it.
	if !isURL(target) && !hasUnpushedSessionsCommon(repo, target, localRef.Hash(), branchName) {
		return nil
	}

	return doPushBranch(ctx, target, branchName)
}

// hasUnpushedSessionsCommon checks if the local branch differs from the remote.
// Returns true if there's any difference that needs syncing (local ahead, remote ahead, or diverged).
func hasUnpushedSessionsCommon(repo *git.Repository, remote string, localHash plumbing.Hash, branchName string) bool {
	// Check for remote tracking ref: refs/remotes/<remote>/<branch>
	remoteRefName := plumbing.NewRemoteReferenceName(remote, branchName)
	remoteRef, err := repo.Reference(remoteRefName, true)
	if err != nil {
		// Remote branch doesn't exist yet - we have content to push
		return true
	}

	// If local and remote point to same commit, nothing to sync
	// This is the only case where we skip - any difference needs handling
	return localHash != remoteRef.Hash()
}

// doPushBranch pushes the given branch to the target with fetch+merge recovery.
// The target can be a remote name or a URL.
func doPushBranch(ctx context.Context, target, branchName string) error {
	displayTarget := target
	if isURL(target) {
		displayTarget = "checkpoint remote"
	}

	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
	stop := startProgressDots(os.Stderr)

	// Try pushing first
	if result, err := tryPushSessionsCommon(ctx, target, branchName); err == nil {
		finishPush(stop, result, ctx, target)
		return nil
	}
	stop("")

	// Push failed - likely non-fast-forward. Try to fetch and rebase.
	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", branchName)
	stop = startProgressDots(os.Stderr)

	if err := fetchAndRebaseSessionsCommon(ctx, target, branchName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", branchName, err)
		printCheckpointRemoteHint(target)
		return nil // Don't fail the main push
	}
	stop(" done")

	// Try pushing again after rebase
	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", branchName, displayTarget)
	stop = startProgressDots(os.Stderr)

	if result, err := tryPushSessionsCommon(ctx, target, branchName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", branchName, err)
		printCheckpointRemoteHint(target)
	} else {
		finishPush(stop, result, ctx, target)
	}

	return nil
}

// printCheckpointRemoteHint prints a hint when a push to a checkpoint URL fails.
// Only prints when the target is a URL (not the user's default remote).
func printCheckpointRemoteHint(target string) {
	if !isURL(target) {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
	fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
}

// settingsHintOnce ensures the settings commit hint prints at most once per process.
var settingsHintOnce sync.Once

// printSettingsCommitHint prints a hint after a successful checkpoint remote push
// when the committed .entire/settings.json does not contain a checkpoint_remote config.
// entire.io discovers the external checkpoint repo by reading the committed project
// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
// (not just in settings.local.json or uncommitted local changes).
// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
// single pre-push invocation.
func printSettingsCommitHint(ctx context.Context, target string) {
	if !isURL(target) {
		return
	}
	settingsHintOnce.Do(func() {
		if isCheckpointRemoteCommitted(ctx) {
			return
		}
		fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
	})
}

// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
// at HEAD contains a valid checkpoint_remote configuration. This is the true
// discoverability check: entire.io reads from committed project settings, not from
// local overrides or uncommitted changes.
func isCheckpointRemoteCommitted(ctx context.Context) bool {
	cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
	output, err := cmd.Output()
	if err != nil {
		return false // file doesn't exist at HEAD
	}
	// Parse the committed content and check for checkpoint_remote
	committed, err := settings.LoadFromBytes(output)
	if err != nil {
		return false
	}
	return committed.GetCheckpointRemote() != nil
}

// pushResult describes what happened during a push attempt.
type pushResult struct {
	// upToDate is true when the remote already had all commits (nothing transferred).
	upToDate bool
}

// parsePushResult checks git push output for known status strings and returns
// a pushResult. git prints "Everything up-to-date" to stderr when nothing was pushed.
func parsePushResult(output string) pushResult {
	return pushResult{
		upToDate: strings.Contains(output, "Everything up-to-date") ||
			strings.Contains(output, "everything up-to-date"),
	}
}

// finishPush stops the progress dots and prints "already up-to-date" or "done"
// depending on the push result. Only prints the settings commit hint when new
// content was actually pushed.
func finishPush(ctx context.Context, stop func(string), result pushResult, target string) {
	if result.upToDate {
		stop(" already up-to-date")
	} else {
		stop(" done")
		printSettingsCommitHint(ctx, target)
	}
}

// tryPushSessionsCommon attempts to push the sessions branch.
func tryPushSessionsCommon(ctx context.Context, remote, branchName string) (pushResult, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Use --no-verify to prevent recursive hook calls
	cmd := CheckpointGitCommand(ctx, remote, "push", "--no-verify", remote, branchName)

	output, err := cmd.CombinedOutput()
	outputStr := string(output)
	if err != nil {
		// Check if it's a non-fast-forward error (we can try to recover)
		if strings.Contains(outputStr, "non-fast-forward") ||
			strings.Contains(outputStr, "rejected") {
			return pushResult{}, errors.New("non-fast-forward")
		}
		return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
	}

	return parsePushResult(outputStr), nil
}

// fetchAndRebaseSessionsCommon fetches remote sessions and rebases local commits
// on top of the remote tip. Since checkpoint shards use unique paths, rebases
// always apply cleanly.
// The target can be a remote name or a URL.
func fetchAndRebaseSessionsCommon(ctx context.Context, target, branchName string) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Determine fetch refspec. When target is a URL, use a temp ref;
	// when it's a remote name, use the standard remote-tracking ref.
	var fetchedRefName plumbing.ReferenceName
	var refSpec string
	if isURL(target) {
		tmpRef := "refs/entire-fetch-tmp/" + branchName
		refSpec = fmt.Sprintf("+refs/heads/%s:%s", branchName, tmpRef)
		fetchedRefName = plumbing.ReferenceName(tmpRef)
	} else {
		refSpec = fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, target, branchName)
		fetchedRefName = plumbing.NewRemoteReferenceName(target, branchName)
	}

	// Use git CLI for fetch (go-git's fetch can be tricky with auth).
	// Use --filter=blob:none for a partial fetch that downloads only commits
	// and trees, skipping blobs. The merge only needs the tree structure to
	// combine entries; blobs are already local or fetched on demand.
	fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, refSpec)
	if output, err := fetchCmd.CombinedOutput(); err != nil {
		return fmt.Errorf("fetch failed: %s", output)
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open git repository: %w", err)
	}

	// Reconcile disconnected metadata branches before rebasing.
	// The fetch above updated the remote-tracking ref, so reconciliation
	// can compare fresh local vs remote. If disconnected (empty-orphan bug),
	// this cherry-picks local commits onto remote tip, updating the local ref.
	// If reconciliation fails, abort — proceeding to rebase on disconnected
	// branches would silently combine unrelated histories.
	if reconcileErr := ReconcileDisconnectedMetadataBranch(ctx, repo, fetchedRefName, os.Stderr); reconcileErr != nil {
		return fmt.Errorf("metadata reconciliation failed: %w", reconcileErr)
	}

	// Get local branch (re-read after potential reconciliation update)
	localRef, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}

	// Get fetched ref (remote-tracking or temp ref, updated by the fetch above)
	remoteRef, err := repo.Reference(fetchedRefName, true)
	if err != nil {
		return fmt.Errorf("failed to get remote ref: %w", err)
	}

	// If local is already at or behind remote, fast-forward
	if localRef.Hash() == remoteRef.Hash() {
		return nil
	}

	// Find merge base
	repoPath, err := getRepoPath(repo)
	if err != nil {
		return fmt.Errorf("failed to get repo path: %w", err)
	}
	mergeBase, err := getMergeBase(ctx, repoPath, localRef.Hash().String(), remoteRef.Hash().String())
	if err != nil {
		return fmt.Errorf("failed to find merge base: %w", err)
	}

	// If local is ancestor of remote (merge base == local), fast-forward to remote
	if mergeBase == localRef.Hash() {
		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
		if err := repo.Storer.SetReference(ref); err != nil {
			return fmt.Errorf("failed to fast-forward branch ref: %w", err)
		}
		if isURL(target) {
			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
		}
		return nil
	}

	// Collect commits reachable from local but not from remote and cherry-pick
	// them onto the remote tip. This preserves local-only commits even when the
	// local metadata branch already contains old merge commits, while avoiding
	// replaying shared ancestors older than the true merge-base.
	localCommits, err := collectCommitsSince(ctx, repo, repoPath, localRef.Hash(), remoteRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to collect local commits: %w", err)
	}

	if len(localCommits) == 0 {
		// No local-only commits — just point to remote
		ref := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), remoteRef.Hash())
		if err := repo.Storer.SetReference(ref); err != nil {
			return fmt.Errorf("failed to update branch ref: %w", err)
		}
		if isURL(target) {
			_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
		}
		return nil
	}

	newTip, err := cherryPickOnto(ctx, repo, remoteRef.Hash(), localCommits)
	if err != nil {
		return fmt.Errorf("failed to rebase local commits onto remote: %w", err)
	}

	// Update branch ref
	newRef := plumbing.NewHashReference(plumbing.NewBranchReferenceName(branchName), newTip)
	if err := repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update branch ref: %w", err)
	}

	// Clean up temp ref if we used one (best-effort, not critical if it fails)
	if isURL(target) {
		_ = repo.Storer.RemoveReference(fetchedRefName) //nolint:errcheck // cleanup is best-effort
	}

	return nil
}

// getMergeBase returns the merge base hash of two commits, or an error if they
// have no common ancestor.
func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
	cmd.Dir = repoPath
	output, err := cmd.Output()
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
	}

	return plumbing.NewHash(strings.TrimSpace(string(output))), nil
}

// collectCommitsSince returns non-merge commits reachable from tip but not from
// exclude, ordered oldest-first in topological order.
func collectCommitsSince(ctx context.Context, repo *git.Repository, repoPath string, tip, exclude plumbing.Hash) ([]*object.Commit, error) {
	ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
	defer cancel()

	// cherryPickOnto computes each commit's delta against its first parent, so
	// replaying merge commits would incorrectly re-apply changes that arrived via
	// non-first-parent history. Limit the replay set to non-merge commits.
	cmd := exec.CommandContext(ctx, "git", "rev-list", "--reverse", "--topo-order", "--no-merges", exclude.String()+".."+tip.String())
	cmd.Dir = repoPath
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("git rev-list failed: %w", err)
	}

	lines := strings.Fields(string(output))
	if len(lines) > MaxCommitTraversalDepth {
		return nil, fmt.Errorf("commit chain exceeded %d commits; aborting rebase", MaxCommitTraversalDepth)
	}

	commits := make([]*object.Commit, 0, len(lines))
	for _, line := range lines {
		hash := plumbing.NewHash(line)
		commit, commitErr := repo.CommitObject(hash)
		if commitErr != nil {
			return nil, fmt.Errorf("failed to get commit %s: %w", hash, commitErr)
		}
		if len(commit.ParentHashes) > 1 {
			continue
		}
		commits = append(commits, commit)
	}

	return commits, nil
}

// startProgressDots prints dots to w every second until the returned stop function
// is called. The stop function prints the given suffix and a newline.
func startProgressDots(w io.Writer) func(suffix string) {
	done := make(chan struct{})
	stopped := make(chan struct{})
	go func() {
		defer close(stopped)
		ticker := time.NewTicker(time.Second)
		defer ticker.Stop()
		for {
			select {
			case <-done:
				return
			case <-ticker.C:
				fmt.Fprint(w, ".")
			}
		}
	}()
	return func(suffix string) {
		close(done)
		<-stopped // Wait for goroutine to finish before writing suffix
		fmt.Fprintln(w, suffix)
	}
}

// isURL returns true if the target looks like a URL rather than a git remote name.
func isURL(target string) bool {
	return strings.Contains(target, "://") || strings.Contains(target, "@")
}

// createMergeCommitCommon creates a merge commit with multiple parents.
func createMergeCommitCommon(repo *git.Repository, treeHash plumbing.Hash, parents []plumbing.Hash, message string) (plumbing.Hash, error) {
	authorName, authorEmail := GetGitAuthorFromRepo(repo)
	now := time.Now()
	sig := object.Signature{
		Name:  authorName,
		Email: authorEmail,
		When:  now,
	}

	commit := &object.Commit{
		TreeHash:     treeHash,
		ParentHashes: parents,
		Author:       sig,
		Committer:    sig,
		Message:      message,
	}

	obj := repo.Storer.NewEncodedObject()
	if err := commit.Encode(obj); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
	}

	hash, err := repo.Storer.SetEncodedObject(obj)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
	}

	return hash, nil
}

package strategy

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/filemode"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// pushRefIfNeeded pushes a custom ref to the given target if it exists locally.
// Custom refs (under refs/entire/) don't have remote-tracking refs, so there's
// no "has unpushed" optimization — we always attempt the push and let git handle
// the no-op case.
func pushRefIfNeeded(ctx context.Context, target string, refName plumbing.ReferenceName) error {
	repo, err := OpenRepository(ctx)
	if err != nil {
		return nil //nolint:nilerr // Hook must be silent on failure
	}

	if _, err := repo.Reference(refName, true); err != nil {
		return nil //nolint:nilerr // Ref doesn't exist locally, nothing to push
	}

	return doPushRef(ctx, target, refName)
}

// tryPushRef attempts to push a custom ref using an explicit refspec.
func tryPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) (pushResult, error) {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Use --no-verify to prevent recursive hook calls (this runs inside pre-push)
	refSpec := fmt.Sprintf("%s:%s", refName, refName)
	cmd := CheckpointGitCommand(ctx, target, "push", "--no-verify", target, refSpec)

	output, err := cmd.CombinedOutput()
	outputStr := string(output)
	if err != nil {
		if strings.Contains(outputStr, "non-fast-forward") ||
			strings.Contains(outputStr, "rejected") {
			return pushResult{}, errors.New("non-fast-forward")
		}
		return pushResult{}, fmt.Errorf("push failed: %s", outputStr)
	}

	return parsePushResult(outputStr), nil
}

// doPushRef pushes a custom ref with fetch+merge recovery on conflict.
func doPushRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
	displayTarget := target
	if isURL(target) {
		displayTarget = "checkpoint remote"
	}

	shortRef := shortRefName(refName)
	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
	stop := startProgressDots(os.Stderr)

	if result, err := tryPushRef(ctx, target, refName); err == nil {
		finishPush(stop, result, ctx, target)
		return nil
	}
	stop("")

	fmt.Fprintf(os.Stderr, "[entire] Syncing %s with remote...", shortRef)
	stop = startProgressDots(os.Stderr)

	if err := fetchAndMergeRef(ctx, target, refName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: couldn't sync %s: %v\n", shortRef, err)
		printCheckpointRemoteHint(target)
		return nil
	}
	stop(" done")

	fmt.Fprintf(os.Stderr, "[entire] Pushing %s to %s...", shortRef, displayTarget)
	stop = startProgressDots(os.Stderr)

	if result, err := tryPushRef(ctx, target, refName); err != nil {
		stop("")
		fmt.Fprintf(os.Stderr, "[entire] Warning: failed to push %s after sync: %v\n", shortRef, err)
		printCheckpointRemoteHint(target)
	} else {
		finishPush(stop, result, ctx, target)
	}

	return nil
}

// fetchAndMergeRef fetches a remote custom ref and merges it into the local ref.
// Uses the same tree-flattening merge as v1 (sharded paths are unique, so no conflicts).
//
// For /full/current: if the remote has archived generations not present locally,
// another machine rotated. In that case, local data is merged into the latest
// archived generation instead of into /full/current (see handleRotationConflict).
func fetchAndMergeRef(ctx context.Context, target string, refName plumbing.ReferenceName) error {
	ctx, cancel := context.WithTimeout(ctx, 2*time.Minute)
	defer cancel()

	// Fetch to a temp ref
	tmpRefSuffix := strings.ReplaceAll(string(refName), "/", "-")
	tmpRefName := plumbing.ReferenceName("refs/entire-fetch-tmp/" + tmpRefSuffix)
	refSpec := fmt.Sprintf("+%s:%s", refName, tmpRefName)

	// Use --filter=blob:none for a partial fetch that downloads only commits
	// and trees, skipping blobs. The merge only needs the tree structure to
	// combine entries; blobs are already local or fetched on demand.
	fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, refSpec)
	fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
	if output, err := fetchCmd.CombinedOutput(); err != nil {
		return fmt.Errorf("fetch failed: %s", output)
	}

	repo, err := OpenRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}
	defer func() {
		_ = repo.Storer.RemoveReference(tmpRefName) //nolint:errcheck // cleanup is best-effort
	}()

	// Check for rotation conflict on /full/current
	if refName == plumbing.ReferenceName(paths.V2FullCurrentRefName) {
		remoteOnlyArchives, detectErr := detectRemoteOnlyArchives(ctx, target, repo)
		if detectErr == nil && len(remoteOnlyArchives) > 0 {
			return handleRotationConflict(ctx, target, repo, refName, tmpRefName, remoteOnlyArchives)
		}
	}

	// Standard tree merge (no rotation detected)
	localRef, err := repo.Reference(refName, true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}
	localCommit, err := repo.CommitObject(localRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get local commit: %w", err)
	}
	localTree, err := localCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get local tree: %w", err)
	}

	remoteRef, err := repo.Reference(tmpRefName, true)
	if err != nil {
		return fmt.Errorf("failed to get remote ref: %w", err)
	}
	remoteCommit, err := repo.CommitObject(remoteRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get remote commit: %w", err)
	}
	remoteTree, err := remoteCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get remote tree: %w", err)
	}

	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten local tree: %w", err)
	}
	if err := checkpoint.FlattenTree(repo, remoteTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten remote tree: %w", err)
	}

	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build merged tree: %w", err)
	}

	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
		[]plumbing.Hash{localRef.Hash(), remoteRef.Hash()},
		"Merge remote "+shortRefName(refName))
	if err != nil {
		return fmt.Errorf("failed to create merge commit: %w", err)
	}

	newRef := plumbing.NewHashReference(refName, mergeCommitHash)
	if err := repo.Storer.SetReference(newRef); err != nil {
		return fmt.Errorf("failed to update ref: %w", err)
	}

	return nil
}

// detectRemoteOnlyArchives discovers archived generation refs on the remote
// that don't exist locally. Returns them sorted ascending (oldest first).
func detectRemoteOnlyArchives(ctx context.Context, target string, repo *git.Repository) ([]string, error) {
	ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
	defer cancel()

	cmd := CheckpointGitCommand(ctx, target, "ls-remote", target, paths.V2FullRefPrefix+"*")
	cmd.Env = append(cmd.Env, "GIT_TERMINAL_PROMPT=0")
	output, err := cmd.Output()
	if err != nil {
		return nil, fmt.Errorf("ls-remote failed: %w", err)
	}

	var remoteOnly []string
	for _, line := range strings.Split(strings.TrimSpace(string(output)), "\n") {
		if line == "" {
			continue
		}
		parts := strings.Fields(line)
		if len(parts) < 2 {
			continue
		}
		refName := parts[1]
		suffix := strings.TrimPrefix(refName, paths.V2FullRefPrefix)
		if suffix == "current" || !checkpoint.GenerationRefPattern.MatchString(suffix) {
			continue
		}
		// Only check for existence, not hash equality. A locally-present archive
		// could be stale if another machine updated it via rotation conflict recovery,
		// but that's unlikely and the checkpoints are still on /main regardless.
		if _, err := repo.Reference(plumbing.ReferenceName(refName), true); err != nil {
			remoteOnly = append(remoteOnly, suffix)
		}
	}

	sort.Strings(remoteOnly)
	return remoteOnly, nil
}

// handleRotationConflict handles the case where remote /full/current was rotated.
// Merges local /full/current into the latest remote archived generation to avoid
// duplicating checkpoint data, then adopts remote's /full/current as local.
func handleRotationConflict(ctx context.Context, target string, repo *git.Repository, refName, tmpRefName plumbing.ReferenceName, remoteOnlyArchives []string) error {
	// Use the latest remote-only archive
	latestArchive := remoteOnlyArchives[len(remoteOnlyArchives)-1]
	archiveRefName := plumbing.ReferenceName(paths.V2FullRefPrefix + latestArchive)

	// Fetch the latest archived generation
	archiveTmpRef := plumbing.ReferenceName("refs/entire-fetch-tmp/archive-" + latestArchive)
	archiveRefSpec := fmt.Sprintf("+%s:%s", archiveRefName, archiveTmpRef)
	fetchCmd := CheckpointGitCommand(ctx, target, "fetch", "--no-tags", "--filter=blob:none", target, archiveRefSpec)
	fetchCmd.Env = append(fetchCmd.Env, "GIT_TERMINAL_PROMPT=0")
	if output, fetchErr := fetchCmd.CombinedOutput(); fetchErr != nil {
		return fmt.Errorf("fetch archived generation failed: %s", output)
	}
	defer func() {
		_ = repo.Storer.RemoveReference(archiveTmpRef) //nolint:errcheck // cleanup is best-effort
	}()

	// Get archived generation state
	archiveRef, err := repo.Reference(archiveTmpRef, true)
	if err != nil {
		return fmt.Errorf("failed to get archived ref: %w", err)
	}
	archiveCommit, err := repo.CommitObject(archiveRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get archive commit: %w", err)
	}
	archiveTree, err := archiveCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get archive tree: %w", err)
	}

	// Get local /full/current state
	localRef, err := repo.Reference(refName, true)
	if err != nil {
		return fmt.Errorf("failed to get local ref: %w", err)
	}
	localCommit, err := repo.CommitObject(localRef.Hash())
	if err != nil {
		return fmt.Errorf("failed to get local commit: %w", err)
	}
	localTree, err := localCommit.Tree()
	if err != nil {
		return fmt.Errorf("failed to get local tree: %w", err)
	}

	// Tree-merge local /full/current into archived generation.
	// Git content-addressing deduplicates shared shard paths automatically.
	entries := make(map[string]object.TreeEntry)
	if err := checkpoint.FlattenTree(repo, archiveTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten archive tree: %w", err)
	}
	if err := checkpoint.FlattenTree(repo, localTree, "", entries); err != nil {
		return fmt.Errorf("failed to flatten local tree: %w", err)
	}

	// Update generation.json timestamps if present in the merged tree.
	// Use the local /full/current HEAD commit time as the newest checkpoint time
	// (more accurate than time.Now() for cleanup scheduling).
	if genEntry, exists := entries[paths.GenerationFileName]; exists {
		if updatedEntry, updateErr := updateGenerationTimestamps(repo, genEntry.Hash, localCommit.Committer.When.UTC()); updateErr == nil {
			entries[paths.GenerationFileName] = updatedEntry
		} else {
			logging.Warn(ctx, "rotation recovery: failed to update generation timestamps, using stale values",
				slog.String("error", updateErr.Error()),
			)
		}
	}

	mergedTreeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
	if err != nil {
		return fmt.Errorf("failed to build merged tree: %w", err)
	}

	// Create commit parented on archive's commit (fast-forward)
	mergeCommitHash, err := createMergeCommitCommon(repo, mergedTreeHash,
		[]plumbing.Hash{archiveRef.Hash()},
		"Merge local checkpoints into archived generation")
	if err != nil {
		return fmt.Errorf("failed to create merge commit: %w", err)
	}

	// Update local archived ref and push it
	newArchiveRef := plumbing.NewHashReference(archiveRefName, mergeCommitHash)
	if err := repo.Storer.SetReference(newArchiveRef); err != nil {
		return fmt.Errorf("failed to update archive ref: %w", err)
	}

	if _, pushErr := tryPushRef(ctx, target, archiveRefName); pushErr != nil {
		return fmt.Errorf("failed to push updated archive: %w", pushErr)
	}

	// Adopt remote's /full/current as local
	remoteRef, err := repo.Reference(tmpRefName, true)
	if err != nil {
		return fmt.Errorf("failed to get fetched /full/current: %w", err)
	}
	adoptedRef := plumbing.NewHashReference(refName, remoteRef.Hash())
	if err := repo.Storer.SetReference(adoptedRef); err != nil {
		return fmt.Errorf("failed to adopt remote /full/current: %w", err)
	}

	return nil
}

// updateGenerationTimestamps reads generation.json from a blob, updates
// newest_checkpoint_at if the provided newestFromLocal is newer, and returns
// an updated tree entry. Uses the local commit timestamp rather than
// time.Now() so cleanup scheduling reflects actual checkpoint creation time.
func updateGenerationTimestamps(repo *git.Repository, genBlobHash plumbing.Hash, newestFromLocal time.Time) (object.TreeEntry, error) {
	blob, err := repo.BlobObject(genBlobHash)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to read generation blob: %w", err)
	}
	reader, err := blob.Reader()
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to open generation blob reader: %w", err)
	}
	defer reader.Close()

	data, err := io.ReadAll(reader)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to read generation blob data: %w", err)
	}

	var gen checkpoint.GenerationMetadata
	if err := json.Unmarshal(data, &gen); err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to parse generation.json: %w", err)
	}

	if newestFromLocal.After(gen.NewestCheckpointAt) {
		gen.NewestCheckpointAt = newestFromLocal
	}

	updatedData, err := jsonutil.MarshalIndentWithNewline(gen, "", "  ")
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to marshal generation.json: %w", err)
	}

	newBlobHash, err := checkpoint.CreateBlobFromContent(repo, updatedData)
	if err != nil {
		return object.TreeEntry{}, fmt.Errorf("failed to create generation blob: %w", err)
	}

	return object.TreeEntry{
		Name: paths.GenerationFileName,
		Mode: filemode.Regular,
		Hash: newBlobHash,
	}, nil
}

// pushV2Refs pushes v2 checkpoint refs to the target.
// Pushes /main, /full/current, and the latest archived generation (if any).
// Older archived generations are immutable and were pushed when created.
func pushV2Refs(ctx context.Context, target string) {
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2MainRefName))        //nolint:errcheck // pushRefIfNeeded handles errors internally
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullCurrentRefName)) //nolint:errcheck // pushRefIfNeeded handles errors internally

	// Push only the latest archived generation (most likely to be newly created)
	repo, err := OpenRepository(ctx)
	if err != nil {
		return
	}
	store := checkpoint.NewV2GitStore(repo, ResolveCheckpointURL(ctx, "origin"))
	archived, err := store.ListArchivedGenerations()
	if err != nil || len(archived) == 0 {
		return
	}
	latest := archived[len(archived)-1]
	_ = pushRefIfNeeded(ctx, target, plumbing.ReferenceName(paths.V2FullRefPrefix+latest)) //nolint:errcheck // pushRefIfNeeded handles errors internally
}

// shortRefName returns a human-readable short form of a ref name for log output.
// e.g., "refs/entire/checkpoints/v2/main" -> "v2/main"
func shortRefName(refName plumbing.ReferenceName) string {
	const prefix = "refs/entire/checkpoints/"
	s := string(refName)
	if strings.HasPrefix(s, prefix) {
		return s[len(prefix):]
	}
	return s
}
